// ReasonContainsFold applies the ContainsFold predicate on the "reason" field.
func ReasonContainsFold(v string) predicate.AgentRefund {
	return predicate.AgentRefund(sql.FieldContainsFold(FieldReason, v))
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AgentRefund) predicate.AgentRefund {
	return predicate.AgentRefund(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AgentRefund) predicate.AgentRefund {
	return predicate.AgentRefund(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AgentRefund) predicate.AgentRefund {
	return predicate.AgentRefund(sql.NotPredicates(p))
}
